    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
};

constexpr std::uint32_t rotr(std::uint32_t x, unsigned n) {
    return (x >> n) | (x << (32 - n));
}

}  // namespace

Sha256::Sha256()
    : state_{0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
             0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19} {}

void Sha256::process_block(const unsigned char* block) {
    std::uint32_t w[64];
    for (int i = 0; i < 16; ++i) {
        w[i] = (static_cast<std::uint32_t>(block[i * 4]) << 24) |
               (static_cast<std::uint32_t>(block[i * 4 + 1]) << 16) |
               (static_cast<std::uint32_t>(block[i * 4 + 2]) << 8) |
               (static_cast<std::uint32_t>(block[i * 4 + 3]));
    }
    for (int i = 16; i < 64; ++i) {
        std::uint32_t s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >> 3);
        std::uint32_t s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >> 10);
        w[i] = w[i - 16] + s0 + w[i - 7] + s1;
    }

    std::uint32_t a = state_[0], b = state_[1], c = state_[2], d = state_[3];
    std::uint32_t e = state_[4], f = state_[5], g = state_[6], h = state_[7];

    for (int i = 0; i < 64; ++i) {
        std::uint32_t s1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
        std::uint32_t ch = (e & f) ^ (~e & g);
        std::uint32_t t1 = h + s1 + ch + kRoundConstants[i] + w[i];
        std::uint32_t s0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
        std::uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
        std::uint32_t t2 = s0 + maj;
        h = g; g = f; f = e; e = d + t1;
        d = c; c = b; b = a; a = t1 + t2;
    }

    state_[0] += a; state_[1] += b; state_[2] += c; state_[3] += d;
    state_[4] += e; state_[5] += f; state_[6] += g; state_[7] += h;
}

void Sha256::update(const unsigned char* data, std::size_t size) {
    total_size_ += size;

    if (buffer_size_ > 0) {
        std::size_t need = 64 - buffer_size_;
        std::size_t take = size < need ? size : need;
        std::memcpy(buffer_.data() + buffer_size_, data, take);
        buffer_size_ += take;
        data += take;
        size -= take;
        if (buffer_size_ == 64) {
            process_block(buffer_.data());
            buffer_size_ = 0;
        }
    }

    while (size >= 64) {
        process_block(data);
        data += 64;
        size -= 64;
    }

    if (size > 0) {
        std::memcpy(buffer_.data(), data, size);
        buffer_size_ = size;
    }
}

std::array<unsigned char, 32> Sha256::finish() {
    std::uint64_t bit_length = total_size_ * 8;

    unsigned char pad = 0x80;
    update(&pad, 1);
    unsigned char zero = 0x00;
    while (buffer_size_ != 56) {
        update(&zero, 1);
    }

    unsigned char length_bytes[8];
    for (int i = 0; i < 8; ++i) {
        length_bytes[i] = static_cast<unsigned char>(bit_length >> (56 - i * 8));
    }
    update(length_bytes, 8);

    std::array<unsigned char, 32> digest{};
    for (int i = 0; i < 8; ++i) {
        digest[i * 4] = static_cast<unsigned char>(state_[i] >> 24);
        digest[i * 4 + 1] = static_cast<unsigned char>(state_[i] >> 16);
        digest[i * 4 + 2] = static_cast<unsigned char>(state_[i] >> 8);
        digest[i * 4 + 3] = static_cast<unsigned char>(state_[i]);
    }
    return digest;
}

FileHashResult hash_file_sha256(const std::filesystem::path& path) {
    std::error_code ec;
    std::filesystem::file_status status = std::filesystem::status(path, ec);
    if (ec) {
        return {false, {}, ec.message()};
    }
    if (!std::filesystem::is_regular_file(status)) {
        if (std::filesystem::is_directory(status)) {
            return {false, {}, "is a directory"};
        }
        return {false, {}, "not a regular file"};
    }

    errno = 0;
    std::ifstream in(path, std::ios::binary);
    if (!in.is_open()) {
        int saved_errno = errno;
        return {false, {}, saved_errno != 0 ? std::strerror(saved_errno)
                                            : std::string("cannot open file")};
    }

    Sha256 sha;
    char chunk[64 * 1024];
    while (in) {
        in.read(chunk, sizeof(chunk));
        std::streamsize got = in.gcount();
        if (got > 0) {
            sha.update(chunk, static_cast<std::size_t>(got));
        }
    }
    if (in.bad()) {
        return {false, {}, "read error"};
    }

    return {true, sha.finish(), {}};
}

std::string to_hex(const std::array<unsigned char, 32>& digest) {
    static constexpr char kDigits[] = "0123456789abcdef";
    std::string hex;
    hex.reserve(64);
    for (unsigned char byte : digest) {
        hex.push_back(kDigits[byte >> 4]);
        hex.push_back(kDigits[byte & 0x0f]);
    }
    return hex;
}

}  // namespace branchaudit

